"""Patches the android/ folder generated by `flutter create` (run right after it).

Does, in order:
  * forces app id / namespace to xyz.xray.vpn and the launcher label to "XRay Vpn"
  * adds permissions + <queries> (needed for the app picker)
  * minSdk 23 + legacy native-library packaging (Xray core ships .so files)
  * installs our MainActivity (tools/native/MainActivity.kt) at the right path
  * writes a launcher icon, removes the default widget test
"""
import glob
import math
import os
import re
import shutil
import io
import struct
import zipfile
import zlib

PKG = "xyz.xray.vpn"
LABEL = "XRay Vpn"
MIN_SDK = "23"

# ---------------------------------------------------------------- manifest
mf = "android/app/src/main/AndroidManifest.xml"
with open(mf, encoding="utf-8") as f:
    s = f.read()

s = re.sub(r'\s+android:extractNativeLibs="(?:true|false)"', "", s)
s = re.sub(r'(<application\b[^>]*?android:label=")[^"]*(")', rf"\g<1>{LABEL}\g<2>", s, count=1)

perms = ""
for perm in (
    "INTERNET",
    "ACCESS_NETWORK_STATE",
    "CHANGE_NETWORK_STATE",
    "FOREGROUND_SERVICE",
    "POST_NOTIFICATIONS",
    "REQUEST_IGNORE_BATTERY_OPTIMIZATIONS",
    # Android 14+: a foreground service with a declared type needs the matching
    # permission, otherwise startForeground() throws and the VPN service dies.
    "FOREGROUND_SERVICE_SYSTEM_EXEMPTED",
    "FOREGROUND_SERVICE_SPECIAL_USE",
):
    tag = f"android.permission.{perm}"
    if tag not in s:
        perms += f'    <uses-permission android:name="{tag}"/>\n'

queries = ""
if "<queries>" not in s:
    queries = (
        "    <queries>\n"
        "        <intent>\n"
        '            <action android:name="android.intent.action.MAIN"/>\n'
        '            <category android:name="android.intent.category.LAUNCHER"/>\n'
        "        </intent>\n"
        "    </queries>\n"
    )

if "android:scheme=\"vless\"" not in s:
    filt = (
        "            <intent-filter>\n"
        '                <action android:name="android.intent.action.VIEW"/>\n'
        '                <category android:name="android.intent.category.DEFAULT"/>\n'
        '                <category android:name="android.intent.category.BROWSABLE"/>\n'
        + "".join(
            f'                <data android:scheme="{sch}"/>\n'
            for sch in ("vless", "vmess", "trojan", "ss", "hysteria2", "hy2")
        )
        + "            </intent-filter>\n"
    )
    i = s.find("</activity>")
    if i >= 0:
        s = s[:i] + filt + "        " + s[i:]
    else:
        # self-closing <activity .../>: open it up
        m_act = re.search(r"<activity\b([^>]*?)/>", s)
        if m_act:
            s = s[: m_act.start()] + "<activity" + m_act.group(1) + ">\n" + filt + "        </activity>" + s[m_act.end():]
        else:
            print("NOTE: no <activity> found; deep links (vless:// ...) were not registered")

if 'xmlns:tools=' not in s:
    s = re.sub(r'<manifest\b', '<manifest xmlns:tools="http://schemas.android.com/tools"', s, count=1)

m = re.search(r"(?m)^([ \t]*)<application\b", s)
if not m:
    raise SystemExit("ERROR: <application> tag not found.")
s = s[: m.start()] + perms + queries + s[m.start():]

services = """
        <service
            android:name="dev.dev7.lib.v2ray.service.V2RayVpnService"
            android:permission="android.permission.BIND_VPN_SERVICE"
            android:process=":v2ray"
            android:foregroundServiceType="systemExempted"
            android:exported="false"
            tools:replace="android:foregroundServiceType,android:process">
            <intent-filter>
                <action android:name="android.net.VpnService" />
            </intent-filter>
        </service>
        <service
            android:name="dev.dev7.lib.v2ray.service.V2RayProxyOnlyService"
            android:process=":v2ray"
            android:foregroundServiceType="specialUse"
            android:exported="false"
            tools:replace="android:foregroundServiceType,android:process">
            <property
                android:name="android.app.PROPERTY_SPECIAL_USE_FGS_SUBTYPE"
                android:value="Proxy service for XRay local tunneling" />
        </service>
        <service
            android:name="id.laskarmedia.openvpn_flutter.OpenVPNService"
            android:permission="android.permission.BIND_VPN_SERVICE"
            android:process=":openvpn"
            android:foregroundServiceType="systemExempted"
            android:exported="false"
            tools:replace="android:foregroundServiceType,android:process">
            <intent-filter>
                <action android:name="android.net.VpnService" />
            </intent-filter>
        </service>
        <service
            android:name="xyz.xray.vpn.TunnelDaemonService"
            android:process=":tunnel"
            android:exported="false" />
"""
if "V2RayVpnService" not in s:
    app_close = s.rfind("</application>")
    if app_close >= 0:
        s = s[:app_close] + services + s[app_close:]

with open(mf, "w", encoding="utf-8") as f:
    f.write(s)

# ------------------------------------------------------------------ gradle
files = glob.glob("android/app/build.gradle*")
if not files:
    raise SystemExit("ERROR: No Android app Gradle build file found.")

for path in files:
    with open(path, encoding="utf-8") as f:
        t = f.read()

    t = re.sub(r"minSdk\s*=\s*[^\n]+", f"minSdk = {MIN_SDK}", t)
    t = re.sub(r"minSdkVersion\s+[^\n]+", f"minSdkVersion {MIN_SDK}", t)
    # applicationId / namespace, groovy and kts syntax
    t = re.sub(r'(namespace\s*=?\s*)["\'][^"\']*["\']', rf'\1"{PKG}"', t)
    t = re.sub(r'(applicationId\s*=?\s*)["\'][^"\']*["\']', rf'\1"{PKG}"', t)

    if "useLegacyPackaging" not in t:
        if path.endswith(".kts"):
            block = (
                "\n    packaging {\n"
                "        jniLibs {\n"
                "            useLegacyPackaging = true\n"
                "            pickFirsts += listOf(\n"
                '                "**/libgojni.so",\n'
                '                "lib/**/libgojni.so"\n'
                "            )\n"
                "        }\n"
                "    }\n"
            )
        else:
            block = (
                "\n    packagingOptions {\n"
                "        jniLibs {\n"
                "            useLegacyPackaging true\n"
                "            pickFirst '**/libgojni.so'\n"
                "            pickFirst 'lib/**/libgojni.so'\n"
                "        }\n"
                "    }\n"
            )
        t, count = re.subn(r"(?m)^android\s*\{", lambda m: m.group(0) + block, t, count=1)
        if count != 1:
            raise SystemExit(f"ERROR: Could not locate android {{ in {path}.")

    # The Xray core, OpenVPN (ics-openvpn) and WireGuard-over-Xray engines are native
    # libraries that call back into Java classes by name over JNI. R8 cannot see those
    # references and strips/renames the classes in release builds, so the core silently
    # never starts. Keep the code unshrunk.
    kts = path.endswith(".kts")
    shrink = (
        "            isMinifyEnabled = false\n            isShrinkResources = false\n"
        if kts
        else "            minifyEnabled false\n            shrinkResources false\n"
    )
    if "isMinifyEnabled" not in t and "minifyEnabled" not in t:
        t, n = re.subn(r"(?m)^(\s*)release\s*\{\s*\n", lambda m: m.group(0) + shrink, t, count=1)
        if n != 1:
            print(f"NOTE: no release block found in {path}; build with --no-shrink instead")
    else:
        t = re.sub(r"isMinifyEnabled\s*=\s*true", "isMinifyEnabled = false", t)
        t = re.sub(r"isShrinkResources\s*=\s*true", "isShrinkResources = false", t)
        t = re.sub(r"minifyEnabled\s+true", "minifyEnabled false", t)
        t = re.sub(r"shrinkResources\s+true", "shrinkResources false", t)

    # Remove any conflicting ndk { abiFilters ... } block to allow splits.abi to manage ABI filtering
    t = re.sub(r'(?s)\n\s*ndk\s*\{\s*abiFilters[^\}]*\}', '', t)

    # Enable ABI splits to build distinct, isolated APKs
    if "splits {" not in t:
        if path.endswith(".kts"):
            splits_block = (
                "\n    splits {\n"
                "        abi {\n"
                "            isEnable = true\n"
                "            reset()\n"
                '            include("arm64-v8a", "armeabi-v7a")\n'
                "            isUniversalApk = false\n"
                "        }\n"
                "    }\n"
            )
        else:
            splits_block = (
                "\n    splits {\n"
                "        abi {\n"
                "            enable true\n"
                "            reset()\n"
                '            include "arm64-v8a", "armeabi-v7a"\n'
                "            universalApk false\n"
                "        }\n"
                "    }\n"
            )
        t, _ = re.subn(r"(?m)^android\s*\{", lambda m: m.group(0) + splits_block, t, count=1)

    # Add local AAR support for custom protocol engines
    os.makedirs("android/app/libs", exist_ok=True)
    if path.endswith(".kts"):
        if "include(listOf" not in t and "fileTree" not in t:
            t += '\ndependencies {\n    implementation(fileTree(mapOf("dir" to "libs", "include" to listOf("*.jar", "*.aar"))))\n}\n'
    else:
        if "flatDir" not in t:
            t += "\nrepositories {\n    flatDir {\n        dirs 'libs'\n    }\n}\n"
        if "fileTree(dir: 'libs'" not in t:
            t += "\ndependencies {\n    implementation fileTree(dir: 'libs', include: ['*.jar', '*.aar'])\n}\n"

    with open(path, "w", encoding="utf-8") as f:
        f.write(t)

    if PKG not in t:
        raise SystemExit(f"ERROR: {PKG} was not applied in {path}")

# Write ProGuard keep rules for JNI callbacks
pg_path = "android/app/proguard-rules.pro"
pg_rules = """
-keep class dev.dev7.lib.v2ray.** { *; }
-keep class com.v2ray.** { *; }
-keep class id.laskarmedia.openvpn_flutter.** { *; }
-keep class de.blinkt.openvpn.** { *; }
-keep class dnstt.** { *; }
-keep class slowdns.** { *; }
-keep class psi.** { *; }
-keep class ca.psiphon.** { *; }
-keep class openconnect.** { *; }
-keep class org.infradead.openconnect.** { *; }
-dontwarn dev.dev7.lib.v2ray.**
-dontwarn id.laskarmedia.openvpn_flutter.**
-dontwarn dnstt.**
-dontwarn slowdns.**
-dontwarn psi.**
-dontwarn ca.psiphon.**
-dontwarn openconnect.**
"""
with open(pg_path, "w", encoding="utf-8") as f:
    f.write(pg_rules)

# ------------------------------------------------------------ MainActivity
for old in glob.glob("android/app/src/main/**/MainActivity.*", recursive=True):
    os.remove(old)
dest_dir = os.path.join("android/app/src/main/kotlin", *PKG.split("."))
os.makedirs(dest_dir, exist_ok=True)
shutil.copy("tools/native/MainActivity.kt", os.path.join(dest_dir, "MainActivity.kt"))
if os.path.exists("tools/native/TunnelDaemonService.kt"):
    shutil.copy("tools/native/TunnelDaemonService.kt", os.path.join(dest_dir, "TunnelDaemonService.kt"))

# ----------------------------------------------------------- launcher icon
def png(w, h, rgba):
    raw = b"".join(b"\x00" + rgba[y * w * 4:(y + 1) * w * 4] for y in range(h))

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        return c + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    return (
        b"\x89PNG\r\n\x1a\n"
        + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
        + chunk(b"IDAT", zlib.compress(raw, 9))
        + chunk(b"IEND", b"")
    )


SHIELD = [(0.5, 0.17), (0.80, 0.27), (0.80, 0.52), (0.5, 0.85), (0.20, 0.52), (0.20, 0.27)]


def inside(px, py, poly):
    c = False
    j = len(poly) - 1
    for i in range(len(poly)):
        xi, yi = poly[i]
        xj, yj = poly[j]
        if (yi > py) != (yj > py) and px < (xj - xi) * (py - yi) / (yj - yi) + xi:
            c = not c
        j = i
    return c


def seg_dist(px, py, a, b):
    ax, ay = a
    bx, by = b
    dx, dy = bx - ax, by - ay
    t = max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy)))
    return math.hypot(px - (ax + t * dx), py - (ay + t * dy))


def icon(size):
    ss = 3
    out = bytearray()
    for y in range(size):
        for x in range(size):
            r = g = b = 0.0
            for sy in range(ss):
                for sx in range(ss):
                    u = (x + (sx + 0.5) / ss) / size
                    v = (y + (sy + 0.5) / ss) / size
                    k = (u + v) / 2
                    col = (15 + 20 * k, 118 - 40 * k, 110 - 30 * k)  # teal gradient
                    if inside(u, v, SHIELD):
                        col = (255, 255, 255)
                        w = 0.055
                        if (
                            seg_dist(u, v, (0.38, 0.36), (0.62, 0.64)) < w
                            or seg_dist(u, v, (0.62, 0.36), (0.38, 0.64)) < w
                        ):
                            col = (15, 100, 95)
                    r += col[0]
                    g += col[1]
                    b += col[2]
            n = ss * ss
            out += bytes((int(r / n), int(g / n), int(b / n), 255))
    return png(size, size, bytes(out))


for folder, px in (("mdpi", 48), ("hdpi", 72), ("xhdpi", 96), ("xxhdpi", 144), ("xxxhdpi", 192)):
    d = f"android/app/src/main/res/mipmap-{folder}"
    os.makedirs(d, exist_ok=True)
    for old in glob.glob(os.path.join(d, "ic_launcher.*")):
        os.remove(old)
    with open(os.path.join(d, "ic_launcher.png"), "wb") as f:
        f.write(icon(px))

# ------------------------------------------------------------------- Ensure valid AAR structure (AndroidManifest.xml + strip duplicate go.Seq)
def strip_go_classes_from_aars():
    libs_dir = "android/app/libs"
    if not os.path.exists(libs_dir):
        return
    for aar_name in os.listdir(libs_dir):
        if not aar_name.endswith(".aar"):
            continue
        aar_path = os.path.join(libs_dir, aar_name)
        clean_name = aar_name[:-4].replace("-", "_").replace(".", "_")
        pkg_name = f"com.custom.{clean_name}"
        manifest_xml = f'<?xml version="1.0" encoding="utf-8"?>\n<manifest xmlns:android="http://schemas.android.com/apk/res/android"\n    package="{pkg_name}">\n    <uses-sdk android:minSdkVersion="23" />\n</manifest>\n'.encode("utf-8")
        try:
            with zipfile.ZipFile(aar_path, "r") as aar_in:
                aar_files = {name: aar_in.read(name) for name in aar_in.namelist()}

            if "classes.jar" not in aar_files:
                continue

            # Ensure AndroidManifest.xml exists with unique package namespace
            aar_files["AndroidManifest.xml"] = manifest_xml

            jar_bytes = aar_files["classes.jar"]
            jar_in_buf = io.BytesIO(jar_bytes)
            jar_out_buf = io.BytesIO()

            modified = True  # force rewrite with AndroidManifest.xml
            with zipfile.ZipFile(jar_in_buf, "r") as jar_in:
                with zipfile.ZipFile(jar_out_buf, "w", compression=zipfile.ZIP_DEFLATED) as jar_out:
                    for item in jar_in.infolist():
                        if item.filename.startswith("go/"):
                            continue  # Skip duplicate go.Seq classes
                        jar_out.writestr(item, jar_in.read(item.filename))

            aar_files["classes.jar"] = jar_out_buf.getvalue()
            with zipfile.ZipFile(aar_path, "w", compression=zipfile.ZIP_DEFLATED) as aar_out:
                for name, content in aar_files.items():
                    aar_out.writestr(name, content)
            print(f"Patched AAR {aar_name} with AndroidManifest.xml and clean classes.jar")
        except Exception as e:
            print(f"Notice patching AAR {aar_name}: {e}")

strip_go_classes_from_aars()

